CREATE TABLE checkout_clearances(id text PRIMARY KEY,admission_id text NOT NULL REFERENCES admissions(id),approved_by text NOT NULL REFERENCES users(id),authority_doctor_id text NOT NULL REFERENCES users(id),approval_source text NOT NULL CHECK(approval_source IN('doctor','reception_on_behalf')),confirmation_note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX checkout_clearance_admission ON checkout_clearances(admission_id,created_at DESC);
CREATE TABLE checkout_requests(id text PRIMARY KEY,admission_id text NOT NULL REFERENCES admissions(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','finalized')),notes text,requested_by text NOT NULL REFERENCES users(id),requested_at timestamptz NOT NULL DEFAULT now(),clearance_id text REFERENCES checkout_clearances(id),finalized_by text REFERENCES users(id),finalized_at timestamptz,version integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX checkout_one_request ON checkout_requests(admission_id);
